/** Transfer to a person or queue */
export type Transfer = {
  id: Id;
  description?: string;
  /** sip_refer = blind SIP REFER of the caller's existing leg; http_request = ask an external bridge to move the session (e.g. into a skill queue). */
  method: "sip_refer" | "http_request";
  /** sip_refer: a number or SIP URI, or a lookup (e.g. by intent). */
  target?: LookupValue;
  /** A template: how a bare number becomes a SIP URI (it may also append URI parameters, e.g. ;sip_h_X-Reason={{args.reason | urlencode}}). Targets that already start with sip: or tel: pass through unchanged. */
  uri_template?: string;
  play_dialtone?: boolean;
  /** SIP headers; values are templates. */
  headers?: {
    [key: string]: string;
  };
  request?: {
    connection: string;
    method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
    path: string;
    /** Template; may use {{target}} for the resolved target (a skill id, say). */
    body?: unknown;
  };
  /** Only transfer while this schedule is open; otherwise run 'closed'. */
  schedule?: string;
  closed?: Action[];
  /** Run first (e.g. register the call as 'transferring' in a platform DB). */
  before?: Action[];
  /** Wait after 'before' so the registration lands before the transfer is attempted. */
  delay_s?: number;
  on_success?: Action[];
  on_failure?: Action[];
};

/** Notification */
export type Notification = {
  id: Id;
  description?: string;
  /** first_success = try the entries in order and stop at the first that works (email, then SMS). */
  strategy?: "first_success" | "all";
  deliver: ({
    via: string;
    to: Recipients;
    subject?: string;
    body: string;
    /** How an email body is sent. Ignored for SMS. */
    content_type?: "text" | "html";
    attachments?: ({
      kind: "transcript";
      filename: string;
      format?: "text" | "json";
    })[];
  })[];
  on_failure?: Action[];
};

