/** Vision */
export type Vision = {
  /** turn_attach = the latest camera frame (or uploaded image) is attached to each caller turn; any vision-capable llm works. continuous = frames stream into a realtime model that can speak unprompted; needs a realtime model. */
  mode?: "off" | "turn_attach" | "continuous";
  /** Longest side in pixels sent to the model. */
  max_dimension?: number;
  /** continuous only. A realtime model does not react to new frames by itself, so the runtime samples frames, diffs them cheaply, and nudges the model only when the picture visibly changed. */
  watch?: {
    sample_interval_s?: number;
    /** Mean per-sample difference (0-255) that counts as a visible change. */
    change_threshold?: number;
    min_seconds_between_prompts?: number;
    on_change?: ActionGenerate;
  };
};

export type Agent = {
  id: Id;
  name: string;
  /** router = front door that only hands off; specialist = does one job; standalone = single-agent bot. */
  kind: "router" | "specialist" | "standalone";
  instructions: {
    role: string;
    /** Extra instruction applied once when the agent takes over. */
    opening?: string;
    rules?: string[];
    /** Extra instruction added only while a condition holds (e.g. 'the caller is not verified yet'). */
    conditional?: {
      when: Condition;
      append: string;
    }[];
  };
  tools: string[];
  /** Knowledge bases in 'inject' mode retrieved for this agent on every caller turn. (Mode 'tool' bases are reached through a knowledge tool instead.) */
  knowledge?: string[];
  handoffs?: ({
    id: Id;
    tool: ToolName;
    /** Tells the LLM when to take this handoff. */
    description: string;
    to: string;
    carry_context?: boolean;
    /** State recorded when this handoff is taken, e.g. the caller's intent for later routing. */
    set_state?: Record<string, unknown>;
    /** Spoken while the handoff happens (covers a slow start). */
    announce?: (Speech | null);
  })[];
  /** Actions run, in order, every time this agent takes over (on the entry agent, after the channel greeting): say a fixed line, show a form, send a notification, set state. If one hands off or ends the call, the rest are ski… */
  on_enter?: Action[];
  vision?: Vision;
  /** Restrict this agent to these channels. Omit for all. */
  channels?: string[];
  overrides?: Overrides;
};

export type Task = {
  id: Id;
  kind: "verification" | "collect_fields" | "confirmation" | "custom";
  description?: string;
  instructions?: string;
  /** Give the task the calling agent's conversation so it uses what the caller already said instead of asking again. */
  use_prior_context?: boolean;
  /** The stages of the task, in order. A step is offered only when its `requires` holds, and later steps cannot be reached before earlier ones have passed: the runtime enforces this, not the model. */
  steps: TaskStep[];
  /** Failed answers allowed per step before it gives up, unless the step sets its own (or, with attempts_scope task, in total). */
  max_attempts?: number;
  /** step = max_attempts is allowed on each step. task = it is the total of failed answers across every step, one lockout for the whole task (a verification that allows three wrong answers in all). Schema 1.2. */
  attempts_scope?: "step" | "task";
  /** The task is already satisfied when this holds (the caller is already verified): it ends at once as a success, asks nothing, and is not offered to the model again. Schema 1.2. */
  skip_if?: Condition;
  /** What the calling agent remembers of the task's own conversation. result_only = only its result (what was collected is in state), which keeps spoken answers such as a date of birth out of the caller agent's history and ke… */
  return_history?: "result_only" | "full";
  /** Override the session inactivity policy while this task runs (e.g. longer while a caller looks for an account number). */
  inactivity?: ({
    enabled?: boolean;
    /** silence = caller AND bot silent for timeout_s, paused while a tool runs (the SDK's away state); user_activity = timeout_s since the caller's last message, bot output ignored. auto = silence on audio channels, user_activi… */
    clock?: "auto" | "silence" | "user_activity";
    timeout_s?: number;
    /** Nudges before on_exhausted. 0 = go straight to on_exhausted. */
    max_nudges?: number;
    /** Nudge n uses nudges[n-1]; the last one repeats. */
    nudges?: SpokenAction[];
    on_exhausted?: {
      do: Action[];
    };
  });
  on_success?: TaskOutcome;
  on_failure?: TaskOutcome;
  on_decline?: TaskOutcome;
};

/** Task step */
export type TaskStep = {
  id: Id;
  /** Schema 1.2 when set. */
  type?: "collect" | "call" | "say";
  /** collect: what the model asks for. */
  ask?: string;
  /** collect: how the caller answers. dtmf = keypad tones taken straight into `store_in`, never seen by the model or written to the transcript: use it for a PIN, OTP or card number. Needs a phone channel. Schema 1.2. */
  input?: "speech" | "dtmf";
  /** collect with input dtmf: how the keys are taken. The entry ends when `num_digits` have been entered or the caller presses `terminator` (# unless you say otherwise). A silence of `timeout_s` with too few keys counts as a … */
  dtmf?: {
    /** Stop as soon as this many digits are in. */
    num_digits?: number;
    /** Give up after this long with no key pressed, counted from the end of the question (default 10). */
    timeout_s?: number;
    /** A key that ends the entry (default #). It ends the entry even when `num_digits` is set (too few digits then counts as a missed attempt), and a terminator pressed before any digit is ignored, because people press # out of… */
    terminator?: string;
  };
  /** collect: the state variable that receives the answer once it has passed `validate`. Mark it `sensitive` for a PIN, OTP or card number. Schema 1.2. */
  store_in?: string;
  /** call and say: the actions to run, for example an http action that stores its answer with to_state. Schema 1.2. */
  do?: Action[];
  /** call: the step has passed when this holds after its actions ran (for example the API answered ok). Omit it and the step passes unless an action failed. collect with a validating tool: the answer is accepted when this hol… */
  pass_when?: Condition;
  /** The step is available only once this holds. Put what must already have succeeded here (identity_verified): it is checked in code. Schema 1.2. */
  requires?: Condition;
  /** Skip this step when the condition holds, e.g. the account is already identified. */
  skip_if?: Condition;
  /** How the answer is checked. A tool decides in code, so the model cannot talk its way past it. */
  validate?: ({
    type: "tool";
    tool: string;
    /** Arguments for the tool as templates; {{value}} is the answer just given (and other state is available). Needed for a keypad answer, which the model never sees; for a spoken answer the model supplies the arguments when th… */
    args?: {
      [key: string]: string;
    };
  } | {
    type: "regex";
    pattern: string;
  });
  /** Attempts allowed on this step. Overrides the task's max_attempts. Schema 1.2. */
  max_attempts?: number;
  /** Run when the attempts are used up, typically a transfer or a handoff; then the task's on_failure applies. Schema 1.2. */
  on_exhausted?: Action[];
};

export type TaskOutcome = {
  outcome?: "verified" | "failed" | "declined";
  set_state?: Record<string, unknown>;
  /** caller = the agent that started the task. */
  resume?: "caller" | "entry";
  /** True = the task says nothing on completion and the caller agent carries on. */
  silent?: boolean;
  /** What the calling agent's model is told when the task ends this way (it reads this as the task tool's result, and may use templates such as {{state.customer.first_name}}). Write it as an instruction: 'The caller is verifi… */
  tell_model?: string;
  /** Start this task next instead of returning to the caller: a chain such as verify, then OTP, then set the PIN. Schema 1.2. */
  next?: string;
  /** Actions run when the task ends this way (a transfer after a failure, a notification after success). Schema 1.2. */
  do?: Action[];
};

export type ToolCommon = {
  id: Id;
  type: string;
  /** The name the LLM sees; defaults to id. Two tools may share a name only if their channels do not overlap: a voice variant and a chat variant of the same tool. */
  name?: ToolName;
  /** Shown to the LLM; says when to use the tool. */
  description?: string;
  /** Only offered on these channels. Omit for all. */
  channels?: string[];
  /** model = after the tool runs, the model answers using its result. none = nothing more is said by the model this turn: use it when the tool's effects already spoke or showed something (a form, a transfer), so the model doe… */
  reply?: "model" | "none";
  /** Run in order after the tool succeeds, each when its condition holds. This is where 'say a fixed line then hang up', 'set the call outcome', or 'hand off on chat only' live, in config rather than in code. */
  effects?: RuleBlock[];
  [key: string]: unknown;
};

export type Precondition = {
  require: Condition;
  on_fail: {
    /** Returned to the LLM instead of running the tool. */
    tool_error: string;
  };
};

export type Tool = ((ToolCommon) & {
  type?: "builtin";
  /** noop does nothing itself; only its effects run (set state, hand off). Use it for a tool whose whole job is a conditional handoff. */
  builtin: "end_call" | "transfer_or_callback" | "return_to_entry" | "send_dtmf" | "collect_dtmf" | "send_form" | "noop";
  params?: Record<string, unknown>;
  /** JSON Schema of the arguments the LLM supplies; mainly for noop. Available to effects as {{args.NAME}}. */
  parameters?: Record<string, unknown>;
} | (ToolCommon) & {
  type?: "task";
  task: string;
  /** Checked before the task starts; if one fails the model is told why and the task does not run (for example 'the caller must have said which account first'). */
  preconditions?: Precondition[];
} | (ToolCommon) & {
  type?: "http";
  connection: string;
  request: {
    method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
    path: string;
    query?: {
      [key: string]: string;
    };
    headers?: {
      [key: string]: string;
    };
    body?: unknown;
  };
  /** JSON Schema of the arguments the LLM supplies. Referenced in templates as {{args.NAME}}. */
  parameters: Record<string, unknown>;
  preconditions?: Precondition[];
  result?: {
    /** Only these response fields are shown to the LLM; everything else is dropped. */
    to_llm?: string[];
    to_state?: {
      [key: string]: string;
    };
    /** Response fields delivered straight to the caller (SMS/email) without ever passing through the LLM. */
    out_of_band?: {
      fields: string[];
      via: string;
      template: string;
    };
  };
  timeout_s?: number;
  retries?: number;
  on_error?: {
    tool_error: string;
  };
  limits?: {
    /** State variable incremented on each call to this tool. */
    count_attempts_in?: string;
  };
} | (ToolCommon) & {
  type?: "mcp";
  server: string;
  /** Explicit allow-list of the server's tools; nothing else is exposed. */
  allow: string[];
  /** Checked before ANY of the server's tools runs, for example that the caller is verified. If one fails the model is told why and nothing is called. */
  preconditions?: Precondition[];
} | (ToolCommon) & {
  type?: "knowledge";
  source: string;
  /** Overrides the knowledge base's own top_k for this tool. */
  top_k?: number;
  /** Told to the model when the search fails (the service is down, it timed out, no index was built). Write it as an instruction to the model. Without it the model is told to answer only from what it surely knows, or to offer… */
  on_error?: {
    tool_error: string;
  };
} | (ToolCommon) & {
  type?: "code";
  runtime?: "python" | "javascript";
  /** Reference to the function, e.g. tools/lookup.py:run. */
  handler: string;
  parameters: Record<string, unknown>;
  preconditions?: Precondition[];
  sandbox?: {
    network?: boolean;
    timeout_s?: number;
    memory_mb?: number;
  };
});

export type Auth = ({
  type: "none";
} | {
  type: "bearer";
  token: SecretRef;
} | {
  type: "api_key";
  header: string;
  key: SecretRef;
} | {
  type: "basic";
  username: SecretRef;
  password: SecretRef;
});

export type Connection = ({
  type: "http";
  base_url: string;
  auth?: Auth;
  headers?: {
    [key: string]: string;
  };
  timeout_s?: number;
} | {
  type: "mcp";
  transport?: "streamable_http" | "sse";
  url: string;
  auth?: Auth;
} | {
  type: "notifier";
  kind?: "sms" | "email";
  provider: string;
  /** Sender number, address or mailbox. */
  from?: string;
  /** Provider credentials, each a secret reference (e.g. tenant_id, client_id, client_secret for microsoft_graph). */
  auth?: {
    [key: string]: SecretRef;
  };
});

/** How a search of this knowledge base behaves. Every field is optional. */
export type KnowledgeRetrieval = {
  /** The longest a search may take. In inject mode the caller waits for it on every turn, so keep it short on a phone line: past it the model answers without the material. In tool mode the model is told the search failed. */
  timeout_s?: number;
  /** Drop passages the source scored below this (only for sources that return a score, higher = better). Leave unset to keep everything the source returns. */
  min_score?: number;
  /** At most this much passage text per search, whole passages best-first (the first one is cut rather than dropped if it alone is longer). Passages are prompt text the model reads on every turn in inject mode, so more is slo… */
  max_chars?: number;
  /** Turn markdown in the passages into plain text. Material full of asterisks, pipes and headings makes a model answer in them, and a voice reads them out. */
  strip_markdown?: boolean;
  /** Inject mode only. What is searched for. last_exchange = the bot's previous reply followed by the caller's newest words, so a follow-up such as 'and how much is that?' still carries its subject. last_user = the caller's n… */
  query_from?: "last_exchange" | "last_user";
  /** Inject mode only. How the material is shown to the model. system works with every model provider. assistant shows it as the bot's own earlier note (what the website bot does); do not use it with Anthropic models, which t… */
  role?: "system" | "assistant";
  /** Inject mode only. The sentence placed before the passages. Defaults to a short note that this is reference information, not instructions. May use {{...}} templates. */
  instruction?: string;
};

export type KnowledgeBase = ({
  id: Id;
  type: "vector_store";
  /** tool = the model decides when to search (needs tool calling); inject = retrieve on every caller turn and add the chunks to the prompt (works without tool calling). */
  mode?: "tool" | "inject";
  /** Chunks retrieved per query (default 4). Raise it when topics are split across many small files. */
  top_k?: number;
  retrieval?: KnowledgeRetrieval;
  /** How the sources are cut into passages when the index is built. Rebuild the index after changing it. */
  chunking?: {
    /** Target passage length in characters. Smaller passages match a question more exactly; larger ones carry more context. */
    size?: number;
    /** Characters repeated from the end of one passage at the start of the next. */
    overlap?: number;
  };
  sources: (({
    type: "url";
    url: string;
    crawl_depth?: number;
  } | {
    type: "file";
    file_id: string;
  }))[];
  embedding?: {
    provider: string;
    model: string;
  };
  refresh?: "manual" | "hourly" | "daily" | "weekly";
} | {
  id: Id;
  type: "rag_api";
  mode?: "tool" | "inject";
  /** Passages asked for per search (default 4). Sent to the service as {{top_k}}. */
  top_k?: number;
  retrieval?: KnowledgeRetrieval;
  connection: string;
  collection?: string;
  /** The request sent for each search. In every string, {{query}} is the search text, {{top_k}} the number of passages and {{collection}} the field above. What the caller said is inserted as plain text, so {{...}} typed by a … */
  request: {
    method: "GET" | "POST";
    path: string;
    /** URL query parameters, e.g. {"q": "{{query}}"} for a GET. */
    query?: {
      [key: string]: string;
    };
    headers?: {
      [key: string]: string;
    };
    /** Template; {{query}}, {{top_k}} and {{collection}} are available. */
    body?: unknown;
  };
  /** Where the passages are in the service's JSON answer. Leave it out for the common shapes: a list, or an object whose chunks / results / documents / hits / matches / passages is a list of strings or of objects with text / … */
  response?: {
    /** Path of the list of results, e.g. $.data.matches. */
    items?: string;
    /** Path, inside each result, of the passage text, e.g. $.document.text. */
    text?: string;
    /** Path, inside each result, of where it came from (shown in the call log only). */
    source?: string;
    /** Path, inside each result, of its relevance score (higher = better), used by retrieval.min_score. */
    score?: string;
    /** Path of a ready-made answer text, for a service that answers a question instead of returning passages. When it is present it is used and the results are ignored. */
    answer?: string;
  };
});

export type OnTrigger = {
  action: "deflect" | "redact_in_logs" | "rewrite" | "block" | "end_call";
  say?: Speech;
};

/** Guardrails */
export type Guardrails = {
  input?: GuardrailRule[];
  output?: GuardrailRule[];
  topics?: {
    allowed?: string[];
    blocked?: string[];
    on_off_topic?: {
      say?: Speech;
      max_strikes: number;
      /** Tool to run after the strikes are used up. */
      then: string;
    };
  };
  escalation?: EscalationRule[];
  limits?: {
    /** The call ends this many seconds after the session starts. */
    max_call_duration_s?: number;
    /** Hard ceiling on total silence regardless of inactivity nudges: seconds since the caller last spoke, typed or pressed a key. The bot's own speech counts as silence; the clock stands still while the caller speaks, a keypad… */
    max_silence_s?: number;
    /** How many times the model may call any tool in one call. The call ends at the next one. */
    max_tool_calls_per_call?: number;
    /** How many times the call may move to another agent. The call ends instead of making the next move. */
    max_handoffs_per_call?: number;
    /** What is said, in full, before the call ends when any limit is reached. Default: an English goodbye; write your own (or a catalogue message) for other languages. Schema 1.2. */
    say?: Speech;
  };
};

export type GuardrailRule = ({
  id: Id;
  type: "prompt_injection";
  enforcement: "code" | "both";
  on_trigger: OnTrigger;
} | {
  id: Id;
  type: "pii_detect";
  entities: string[];
  enforcement: "code" | "both";
  on_trigger: OnTrigger;
} | {
  id: Id;
  type: "field_firewall";
  fields: string[];
  enforcement: "code";
} | {
  id: Id;
  type: "regex_block";
  patterns: string[];
  enforcement: "code" | "both";
  on_trigger: OnTrigger;
} | {
  id: Id;
  type: "statement";
  text: string;
  enforcement: "prompt";
});

export type EscalationRule = {
  id: Id;
  when: {
    intent?: string;
    keywords?: string[];
    sentiment?: "frustrated" | "negative" | "abusive";
    consecutive_turns?: number;
    state?: string;
    equals?: unknown;
    gte?: number;
    lte?: number;
  };
  action: "tool" | "end_call" | "handoff";
  tool?: string;
  to?: string;
  say?: Speech;
};

/** Agent configuration */
export interface AgentConfig {
  $schema?: string;
  /** 1.2 adds, all optionally: sensitive state variables, the collect_dtmf action, typed task steps (collect / call / say) with store_in, requires, per-step attempts and on_exhausted, task chaining (on_*.next), and post_call.… */
  schema_version: "1.1" | "1.2";
  meta: {
    id: Id;
    name: string;
    description?: string;
    /** Semantic version. Publishing creates an immutable version; the runtime loads id@version or id@published. */
    version: string;
    status: "draft" | "published" | "archived";
    environment?: "development" | "staging" | "production";
    tags?: string[];
    owner?: string;
    created_at?: string;
    updated_at?: string;
  };
  runtime: {
    engine: "livekit-agents";
    /** plugins = your own provider keys (works self-hosted); inference = LiveKit Inference (Cloud only). One config targets one mode: model names differ between them. */
    provider_mode: "plugins" | "inference";
    /** Deprecated and ignored: the generic runtime is one worker pool for every bot, and a call names its bot in dispatch metadata ({"bot": id, "ref": "production"}). Kept so older configs still validate; omit it in new ones. */
    dispatch_name?: string;
    /** Which vault the { "secret": NAME } references resolve against. */
    secrets_vault?: string;
    /** Default IANA timezone for spoken times and date formatting. */
    timezone?: string;
    worker?: {
      /** Health/drain endpoint. Give each agent on a host its own. */
      http_port?: number;
      /** Warm worker processes. Lower on shared/small hosts. */
      num_idle_processes?: number;
      initialize_process_timeout_s?: number;
    };
    hangup?: {
      /** Deleting the room hangs up the SIP leg / disconnects the widget when the session ends. */
      delete_room_on_close?: boolean;
      /** Let closing speech finish playing before the line is dropped. */
      drain?: boolean;
    };
  };
  /** Fixed values referenced as {{const.name}} (payment URLs, thresholds, wording variables). Not secrets. */
  constants?: Record<string, unknown>;
  schedules?: {
    [key: string]: Schedule;
  };
  identity?: {
    caller_id?: {
      /** Tried in order; the first that yields a value wins. */
      sources: (({
        from: "participant_attribute";
        name: string;
      } | {
        from: "participant_identity";
        /** Regexes removed from the identity, e.g. ^sip[:_] and @.*$. */
        strip?: string[];
      } | {
        from: "static";
        value: string;
        description?: string;
      }))[];
      normalize?: ({
        type: "none";
      } | {
        type: "e164";
        /** ISO 3166-1 alpha-2. Applied with libphonenumber rules (trunk prefixes, calling code). */
        default_country: string;
      });
    };
  };
  telephony?: {
    pbx?: {
      /** Referenced as {{pbx.host}} in transfer URI templates. */
      host: string;
      port?: number;
      transport?: "udp" | "tcp" | "tls";
      trunk?: string;
      /** Dialled number this bot answers; recorded with call logs. */
      dnis?: string;
    };
    transfers?: Transfer[];
  };
  defaults: {
    language?: {
      primary?: string;
      /** Languages the bot answers in. Every message with per-language text should cover these. */
      speaks?: string[];
      also_understands?: string[];
      auto_detect?: boolean;
    };
    models: {
      stt?: (SttConfig);
      llm: (LlmConfig);
      tts?: (TtsConfig);
      realtime?: (null | (RealtimeConfig));
      vad?: VadConfig;
      turn_detector?: TurnDetectorConfig;
    };
    conversation: Conversation;
    reliability?: {
      /** Per-component API retry policy. SDK defaults: 3 retries, 2s apart, 10s timeout. */
      connection?: {
        stt?: ConnectOptions;
        llm?: ConnectOptions;
        tts?: ConnectOptions;
      };
      /** Consecutive unrecoverable STT/LLM/TTS errors before the session is closed. */
      max_unrecoverable_errors?: number;
      /** Runs as the session closes after unrecoverable errors. Speech cannot finish at that point (the close does not drain, and the TTS may be the failing part), so only a pre-recorded sound, a webhook or a log line are allowed… */
      on_session_error?: {
        do?: ((ActionPlaySound | ActionHttp | ActionLog))[];
      };
    };
  };
  persona: {
    name: string;
    company?: string;
    tone?: string;
    style_rules?: string[];
    /** Injected into every agent's prompt. */
    shared_rules?: string[];
    disclosures?: {
      recording_notice?: string;
    };
  };
  /** A catalogue of fixed lines, referenced as { "message": id } wherever speech is accepted. Text may be one string or per-language; per-language entries must include the primary language. */
  messages?: ({
    id: Id;
    description?: string;
    text: (string | {
      [key: string]: string;
    });
    allow_interruptions?: boolean;
  })[];
  /** Typed per-call variables that tools read and write and that conditions/guardrails refer to. Replaces a hand-written session dataclass. */
  state?: {
    variables: {
      [key: string]: StateVariable;
    };
  };
  channels: Channel[];
  agents: {
    /** The agent that answers first. */
    entry: string;
    items: Agent[];
  };
  tasks?: Task[];
  tools?: Tool[];
  connections?: {
    [key: string]: Connection;
  };
  knowledge?: KnowledgeBase[];
  forms?: Form[];
  notifications?: Notification[];
  wrapups?: Wrapup[];
  guardrails?: Guardrails;
  events?: ({
    /** guardrail_triggered (schema 1.2) runs when an input guardrail matches what the caller said; it sees {{rule}}, {{type}}, {{action}} and {{kinds}} (never the words), so a hook can notify or set state, but it cannot hand of… */
    on: "call_started" | "call_ended" | "handoff" | "tool_error" | "session_error" | "escalation" | "inactivity" | "transfer_succeeded" | "transfer_failed" | "state_changed" | "guardrail_triggered" | "limit_reached";
    when?: Condition;
    do: Action[];
  })[];
  post_call?: {
    summary?: {
      enabled: boolean;
      llm?: LlmConfig;
      prompt?: string;
    };
    analysis?: ({
      id: Id;
      type: "boolean" | "enum" | "string" | "number";
      values?: string[];
      question: string;
    })[];
    recording?: {
      audio?: boolean;
      transcript?: boolean;
      retention_days?: number;
    };
    /** Sensitive text is replaced before a transcript or metrics file is written, before `call.transcript` is used in an API call or an email attachment, and in the per-call log and the worker's `log` lines. Entities and patter… */
    redaction?: {
      enabled?: boolean;
      /** Kinds of value to find and replace. */
      entities?: ("card_number" | "bank_account" | "national_id" | "phone_number" | "email" | "date_of_birth" | "otp" | "pin")[];
      /** Extra regular expressions whose matches are replaced. */
      patterns?: string[];
      replacement?: string;
      /** Also mask the exact value of every `sensitive` state variable wherever it appears. */
      mask_sensitive_state?: boolean;
    };
    /** Per-session files or payloads written when the session ends (any shutdown reason). */
    artifacts?: ({
      kind: "transcript" | "metrics";
      enabled?: boolean;
      sink: ({
        type: "file";
        directory: string;
        filename?: string;
      } | {
        type: "http";
        connection: string;
        method: "POST" | "PUT" | "PATCH";
        path: string;
      });
    })[];
  };
  observability?: {
    log_level?: "DEBUG" | "INFO" | "WARNING" | "ERROR";
    log_pii?: boolean;
    /** Record full model requests (everything sent to the model, every turn). The runtime writes them to the call's session log, as `session_log.detail: full` does. Logs conversation content; keep off in production. */
    log_llm_requests?: boolean;
    /** One file per call in the bot's own folder, written as the call runs (a call that crashes still leaves its file): what the caller said, each model request, every tool call with arguments, result and duration, every API ca… */
    session_log?: {
      enabled?: boolean;
      /** Folder name inside the bot's own folder. It cannot be an absolute path or contain `..`. */
      directory?: string;
      /** `events` = what happened. `full` adds every model request in full and the query, request body and response of every API call. Keep `full` for testing. */
      detail?: "events" | "full";
      /** Delete this bot's session files older than this many days. Checked when a call starts, at most once an hour. If it is not set, files are kept, unless whoever runs the workers sets AGENT_RUNTIME_SESSION_RETENTION_DAYS as … */
      retention_days?: number;
    };
    log_file?: {
      path: string;
      max_bytes?: number;
      backup_count?: number;
    };
    metrics?: boolean;
    tracing?: boolean;
    otel?: {
      enabled: boolean;
      /** OTLP HTTP collector, e.g. a self-hosted SigNoz. */
      endpoint?: string;
      service_name?: string;
    };
  };
  tests?: ({
    id: Id;
    /** What this scenario shows, for the person reading the results. */
    description?: string;
    channel: string;
    /** Pretend it is this moment (with a time zone), so a schedule such as business hours is open or closed as the scenario needs. Without it the scenario runs on the real clock. */
    now?: string;
    /** State values set before the conversation starts, over the config's own starting values: 'a caller who is already verified'. */
    state?: Record<string, unknown>;
    /** Answers for the API calls the bot makes during this scenario, tried in order, first match wins. A test run never calls a real API unless it is told to (`allow_network`): a call that no mock matches is answered 404 and li… */
    http_mocks?: ({
      /** Only requests to this connection. Omit to match any. */
      connection?: string;
      /** Omit to match any. */
      method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
      /** The request path, exactly or with * as a wildcard: /orders/* matches /orders/NB-1001. */
      path: string;
      /** Query parameters the request must have (others are allowed). */
      query?: {
        [key: string]: string;
      };
      /** Fields the JSON body must have, with these values (others are allowed): tells two POSTs to the same path apart. */
      body_contains?: Record<string, unknown>;
      status?: number;
      /** The JSON the API answers with. */
      json?: unknown;
      /** Or a plain-text answer. */
      text?: string;
      /** Answer only this many times, then this mock no longer matches (a call that fails the first time and works the second). */
      times?: number;
    })[];
    /** Replaces the language model with a script, one item per model reply: a string (the model says it) or {tool, args} (the model calls that tool). The conversation runs through the real runtime, so prompts, tools, preconditi… */
    model_script?: ((string | {
      tool: string;
      args?: Record<string, unknown>;
    }))[];
    caller?: {
      phone?: string;
      persona?: string;
    };
    turns: (({
      say: string;
    } | {
      /** The caller presses these keys on the phone keypad (a phone channel only), for example 4821#. The digits are never written to the result. */
      keys: string;
    }))[];
    expect: (({
      tool_called: string;
    } | {
      tool_not_called: string;
    } | {
      state_equals: {
        state: string;
        value: unknown;
      };
    } | {
      /** Some assistant message matches this regex (ignoring case). */
      said_matches: string;
    } | {
      /** Natural-language criterion graded by an LLM. Needs a live model, so it is skipped in a scenario that has a model_script. */
      judge: string;
    } | {
      /** The conversation ends with this agent in charge. */
      agent_is: string;
    } | {
      tool_called_with: {
        tool: string;
        /** Arguments the call must include, with these values (others are allowed). */
        args: Record<string, unknown>;
      };
    } | {
      /** The bot made this API request (whether or not a mock answered it). */
      http_called: {
        method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
        /** Exactly, or with * as a wildcard. */
        path: string;
        /** Exactly this many times. Omit for at least once. */
        times?: number;
      };
    } | {
      /** The bot never made this API request: the way to prove a guarded action (a return, a payment link) did not happen. */
      http_not_called: {
        method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
        /** Exactly, or with * as a wildcard. */
        path: string;
      };
    } | {
      /** A task ran and ended this way. Every task of a chain counts, and a task skipped because it was already satisfied counts as `verified`. */
      task_outcome: {
        task: string;
        /** The outcome name: the `outcome` of the task's on_success / on_failure / on_decline block, or verified / failed / declined when it names none. Omit for any outcome. */
        outcome?: string;
      };
    } | {
      /** An input guardrail matched what the caller said (schema 1.2). The way to prove an injection attempt is refused, or that a card number is caught. */
      guardrail_triggered: {
        rule: string;
        /** Also require that the rule acted this way. Omit for any. */
        action?: "deflect" | "redact_in_logs" | "rewrite" | "block" | "end_call";
      };
    } | {
      /** This call limit ended the call (schema 1.2). A scenario is far shorter than the duration and silence limits, so those two can only be proved in a unit test. */
      limit_reached: "max_call_duration_s" | "max_silence_s" | "max_tool_calls_per_call" | "max_handoffs_per_call";
    } | {
      /** This input rule did not match anything: the way to prove an ordinary request is not refused. Schema 1.2. */
      guardrail_not_triggered: string;
    }))[];
  })[];
  builder?: {
    lint?: {
      max_prompt_words_per_agent?: number;
      max_tools_per_agent?: number;
      warn_on_monolith?: boolean;
    };
    ui?: {
      graph_positions?: {
        [key: string]: {
          x: number;
          y: number;
        };
      };
    };
  };
}
